const src = $('Load Business Data').first().json;
const base = src.base_data;
const chat = src.chat_request;
const raw = $input.first().json.text || '';

function parseJSON(t) {
  t = String(t).replace(/```json|```/g, '').trim();
  return JSON.parse(t.slice(t.indexOf('{'), t.lastIndexOf('}') + 1));
}
let intake = null, parseError = null;
try { intake = parseJSON(raw); } catch (err) { parseError = err.message; }

const dataIssues = [], changes = [];
let suppliers;
const req = Object.assign({}, base.requirements);
if (intake && Array.isArray(intake.suppliers) && intake.suppliers.length) {
  suppliers = intake.suppliers;
  if (intake.requirements) for (const k of Object.keys(intake.requirements)) {
    const v = intake.requirements[k];
    if (v !== null && v !== undefined) req[k] = v;
  }
  (intake.changes_applied || []).forEach(x => changes.push(x));
  (intake.data_issues || []).forEach(x => dataIssues.push(x));
} else {
  suppliers = base.suppliers;
  dataIssues.push('Intake agent output could not be parsed (' + (parseError || 'no suppliers') + '). Original dataset used unchanged; changes from the manager chat message were NOT applied.');
}

const num = v => (v === null || v === undefined || v === '' || isNaN(Number(v))) ? null : Number(v);
const npr = n => 'NPR ' + Number(n).toLocaleString('en-US');
const toBool = v => {
  if (v === true || /^(true|yes|included)$/i.test(String(v))) return true;
  if (v === false || /^(false|no|excluded)$/i.test(String(v))) return false;
  return null;
};

const notes = [
  'Delivery within 14 days is listed as "Required" in the Purchase Request but as "Preferred" in the Operations Policy. It is treated here as a preference: any miss is flagged for the Operations Manager to interpret, not used to disqualify.',
  'Payment terms of 30 days after delivery are a preference in both documents. Other terms are flagged as a risk, not a disqualification.'
];

const results = suppliers.map(s => {
  const c = {};
  const set = (key, label, type, status, detail) => { c[key] = { label, type, status, detail }; };
  const total = num(s.total_price), unit = num(s.unit_price), qty = num(s.quantity);
  const ram = num(s.ram_gb), sto = num(s.storage_gb), war = num(s.warranty_years);
  const del = num(s.delivery_days), rat = num(s.rating), late = num(s.late_deliveries);
  const vat = toBool(s.vat_included);

  // ---- Mandatory requirements ----
  if (total === null) set('budget', 'Budget', 'mandatory', 'cannot_verify', 'Total price not available');
  else if (total > req.max_budget_npr) set('budget', 'Budget', 'mandatory', 'fail', npr(total) + ' exceeds maximum ' + npr(req.max_budget_npr));
  else if (vat === false) set('budget', 'Budget', 'mandatory', 'review', npr(total) + ' is within budget BUT VAT is NOT included, so the final cost may exceed the budget');
  else set('budget', 'Budget', 'mandatory', 'pass', npr(total) + ' within maximum ' + npr(req.max_budget_npr));

  if (qty === null) set('quantity', 'Quantity', 'mandatory', 'cannot_verify', 'Quoted quantity not available');
  else if (qty !== req.quantity) set('quantity', 'Quantity', 'mandatory', 'fail', 'Quoted ' + qty + ' units, required ' + req.quantity);
  else set('quantity', 'Quantity', 'mandatory', 'pass', qty + ' units quoted');

  if (ram === null) set('ram', 'RAM', 'mandatory', 'cannot_verify', 'RAM not stated');
  else set('ram', 'RAM', 'mandatory', ram >= req.min_ram_gb ? 'pass' : 'fail', ram + ' GB vs minimum ' + req.min_ram_gb + ' GB');

  if (sto === null) set('storage', 'SSD storage', 'mandatory', 'cannot_verify', 'Storage not stated');
  else set('storage', 'SSD storage', 'mandatory', sto >= req.min_storage_gb ? 'pass' : 'fail', sto + ' GB vs minimum ' + req.min_storage_gb + ' GB');

  const os = String(s.os || '');
  if (!os) set('os', 'Operating system', 'mandatory', 'cannot_verify', 'OS not stated');
  else set('os', 'Operating system', 'mandatory', /windows\s*11\s*pro/i.test(os) ? 'pass' : 'fail', '"' + os + '" vs required Windows 11 Pro');

  const proc = String(s.processor || '');
  const m = proc.match(/i\s*-?\s*([3579])/i);
  if (!proc) set('processor', 'Processor', 'mandatory', 'cannot_verify', 'Processor not stated');
  else if (m) set('processor', 'Processor', 'mandatory', Number(m[1]) >= 5 ? 'pass' : 'fail', '"' + proc + '" vs minimum Intel Core i5 or equivalent');
  else set('processor', 'Processor', 'mandatory', 'unclear', '"' + proc + '" - equivalence to Intel Core i5 needs human interpretation');

  if (war === null) set('warranty', 'Warranty', 'mandatory', 'cannot_verify', 'Warranty not stated');
  else set('warranty', 'Warranty', 'mandatory', war >= req.min_warranty_years ? 'pass' : 'fail', war + ' year(s) vs minimum ' + req.min_warranty_years + ' years');

  // ---- Preferences ----
  if (del === null) set('delivery', 'Delivery time', 'preference', 'cannot_verify', 'Delivery time not stated');
  else set('delivery', 'Delivery time', 'preference', del <= req.max_delivery_days ? 'pass' : 'not_met', del + ' days vs ' + req.max_delivery_days + ' days (see interpretation note on required vs preferred)');

  const pay = String(s.payment_terms || '');
  if (!pay) set('payment', 'Payment terms', 'preference', 'cannot_verify', 'Payment terms not stated');
  else if (/advance/i.test(pay)) set('payment', 'Payment terms', 'preference', 'not_met', '"' + pay + '" vs preferred ' + req.payment_preference + ' (advance payment = cash-flow risk)');
  else if (/30\s*days?\s*after\s*delivery/i.test(pay)) set('payment', 'Payment terms', 'preference', 'pass', '"' + pay + '"');
  else set('payment', 'Payment terms', 'preference', 'unclear', '"' + pay + '" - differs from preferred wording; needs human interpretation');

  // ---- Policy flags ----
  if (rat === null) set('rating', 'Supplier rating', 'policy_flag', 'cannot_verify', 'Rating not available');
  else set('rating', 'Supplier rating', 'policy_flag', rat < req.rating_review_below ? 'review' : 'pass', rat + '/5 (management review if below ' + req.rating_review_below + ')');

  if (late === null) set('late', 'Late deliveries (last year)', 'policy_flag', 'cannot_verify', 'Late delivery count not available');
  else set('late', 'Late deliveries (last year)', 'policy_flag', late > req.late_delivery_flag_above ? 'review' : 'pass', late + ' late deliveries (flag if more than ' + req.late_delivery_flag_above + ')');

  // ---- Information / consistency ----
  if (vat === null) set('tax', 'Tax (VAT) information', 'policy_flag', 'cannot_verify', 'VAT treatment not stated');
  else set('tax', 'Tax (VAT) information', 'policy_flag', 'pass', vat ? 'VAT included' : 'VAT NOT included');

  if (unit !== null && qty !== null && total !== null && unit * qty !== total) {
    set('price_consistency', 'Price arithmetic', 'info', 'review', 'Unit price x quantity = ' + npr(unit * qty) + ' but stated total is ' + npr(total));
    dataIssues.push(s.name + ': unit price x quantity (' + npr(unit * qty) + ') does not match stated total (' + npr(total) + ').');
  }
  const val = num(s.validity_days);
  set('validity', 'Quotation validity', 'info', val === null ? 'cannot_verify' : 'pass', val === null ? 'Validity period not stated' : val + ' days');
  set('quality', 'Quality complaints (info only)', 'info', 'pass', (num(s.quality_complaints) === null ? 'not available' : s.quality_complaints) + ' complaint(s); ' + (s.orders_last_year ?? 'n/a') + ' orders last year; ' + (s.relationship_years ?? 'n/a') + ' years relationship');

  const missing = [];
  if (war === null) missing.push('warranty');
  if (vat === null) missing.push('tax (VAT) information');
  if (del === null) missing.push('delivery time');
  if (!pay) missing.push('payment terms');

  const mand = ['budget', 'quantity', 'ram', 'storage', 'os', 'processor', 'warranty'];
  const fails = mand.filter(k => c[k].status === 'fail');
  const unresolved = mand.filter(k => ['cannot_verify', 'unclear'].includes(c[k].status));
  const flags = Object.keys(c).filter(k => ['review', 'not_met'].includes(c[k].status) || (c[k].status === 'unclear' && !mand.includes(k)));

  let overall = 'FULLY_COMPLIANT';
  if (fails.length) overall = 'NON_COMPLIANT';
  else if (unresolved.length || missing.length) overall = 'NEEDS_CLARIFICATION';
  else if (flags.length) overall = 'COMPLIANT_WITH_FLAGS';

  return {
    name: s.name, product: s.product, quote_and_history: s, checks: c,
    missing_information: missing,
    mandatory_failures: fails.map(k => c[k].label + ': ' + c[k].detail),
    unresolved_mandatory: unresolved.map(k => c[k].label + ': ' + c[k].detail),
    flags: flags.map(k => c[k].label + ': ' + c[k].detail),
    overall_status: overall,
    management_review_required: flags.length > 0 || overall !== 'FULLY_COMPLIANT'
  };
});

return [{ json: { requirements: req, suppliers: results, changes_applied: changes, data_issues: dataIssues, interpretation_notes: notes, chat_request: chat } }];

