const clean = t => String(t || '').replace(/```html|```/gi, '').trim();
const parse = t => { t = String(t || '').replace(/```json|```/g, '').trim(); return JSON.parse(t.slice(t.indexOf('{'), t.lastIndexOf('}') + 1)); };
let rec = {}, qa = {};
try { rec = parse($('Agent 3 - Recommendation').first().json.text); } catch (e) {}
try { qa = parse($('Agent 4 - QA Critic').first().json.text); } catch (e) {}
let html = clean($('Agent 5 - Report Writer').first().json.text);
const qaPass = String(qa.verdict || '').toUpperCase() === 'PASS';
if (!qaPass) {
  html = '<p style="background:#fff3cd;padding:8px;border:1px solid #e0a800"><b>WARNING: the QA Critic did not fully pass this evaluation. Review the QA section carefully before deciding.</b></p>' + html;
}
const summary =
  '**Evaluation complete.**\n\n' +
  '- Recommendation status: ' + (rec.recommendation_status || 'see report') + '\n' +
  '- Suggested supplier: ' + (rec.recommended_supplier || 'none') + '\n' +
  '- QA check: ' + (qa.verdict || 'unknown') + '\n\n' +
  'The full report has been emailed to the Operations Manager. The workflow is now waiting for their Approve / Decline response. This is a recommendation only - the final purchasing decision stays with the Operations Manager.';
return [{ json: { html, chat_summary: summary, recommended_supplier: rec.recommended_supplier || null, qa_verdict: qa.verdict || null } }];
